254	              if (which != NULL)
255	                {
256	                  *which = ctx->name;
257	                }
258	
259	              return &ctx->map[j];
260	            }
261	        }
262	    }
263	
264	  for (i = 0; i < g_global_ctx.nmap; i++)
265	    {
266	      if (g_global_ctx.map[i].keys == keys &&
267	          g_global_ctx.map[i].gesture == g)
268	        {
269	          if (which != NULL)
270	            {
271	              *which = g_global_ctx.name;
272	            }
273	
274	          return &g_global_ctx.map[i];
275	        }
276	    }
277	
278	  return NULL;
279	}
