int bk7258_buttons_input_initialize(void)
{
  pthread_t tid;
  pthread_attr_t attr;
  int ret;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  ret = pthread_create(&tid, &attr, key_thread, NULL);
  pthread_attr_destroy(&attr);
  return ret == 0 ? 0 : -EIO;
}

