562	static void button_source_poll(void)
563	{
564	  struct pollfd pfd;
565	  btn_buttonset_t set;
566	  ssize_t n;
567	  int ret;
568	
569	  pfd.fd = s_fd;
570	  pfd.events = POLLIN;
571	  ret = poll(&pfd, 1, POLL_SLICE_MS);
572	  (void)ret;
573	
574	  /* gesture_update must run every slice, not only when poll reports data:
575	   * the deferred TAP and the HOLD timer are deadlines, and skipping the
576	   * quiet slices pushed them to the next key event -- which is why a tap
577	   * printed only when something else was pressed afterwards.
578	   *
579	   * The level is sampled every slice for the same reason.  poll() only
580	   * shortens the wait; read() returns the live GPIO level, so a lost edge
581	   * heals within one slice.  Reading only on POLLIN left KEY4 "held" after
582	   * a PTT whose release edge never reached us, and its RELEASE then fired
583	   * on the next KEY1 tap during an approval (board log).
584	   */
585	
586	  n = read(s_fd, &set, sizeof(set));
587	  if (n == sizeof(set))
588	    {
589	      s_held = (uint32_t)set;
590	    }
591	
592	  /* Report an edge the interrupt path never delivered.  The upper half
593	   * debounces for 30 ms before notifying, so a short mismatch is normal;
594	   * only one that outlives 200 ms without POLLIN is a lost edge.
595	   */
596	
597	  if (ret > 0)
598	    {
599	      s_irq_held = s_held;
600	    }
601	
602	  if (s_held != s_irq_held)
603	    {
604	      if (!s_skew)
605	        {
606	          s_skew = true;
607	          s_skew_ms = now_ms();
608	        }
609	      else if (!s_skew_reported &&
610	               (uint32_t)(now_ms() - s_skew_ms) >= 200)
611	        {
612	          s_skew_reported = true;
613	          printf("[key] missed edge: irq=%lx level=%lx\n",
614	                 (unsigned long)s_irq_held, (unsigned long)s_held);
615	          key3_regs("missed edge");
616	        }
617	    }
618	  else
619	    {
620	      s_skew = false;
621	      s_skew_reported = false;
622	    }
623	
624	  gesture_update(now_ms());
625	}
