17	/**
18	 * lvgl_toast.c — Top-of-screen toast popup (transient notice, not in chat history).
19	 *
20	 * Pattern follows qrcode_display.c: an async entry copies the request onto the
21	 * heap and lv_async_call()'s into the LVGL thread, where the real widget is
22	 * built on top of lv_screen_active().  A one-shot lv_timer triggers a fade-out
23	 * animation that deletes the object; a CLICKED handler allows early dismiss.
24	 *
25	 * Only one toast is shown at a time — a newer toast replaces an older one.
26	 */
27	
28	#include "ui/lvgl_toast.h"
29	#include "ui/ui_palette.h"
30	#include "agent_config.h"
31	
32	#include <string.h>
33	#include <stdlib.h>
34	#include <syslog.h>
35	
36	#if defined(CONFIG_AI_AGENT_LVGL_UI) && defined(CONFIG_GRAPHICS_LVGL)
37	#include <lvgl/lvgl.h>
38	
39	/* App-owned pre-rasterized MiSans-16 CJK font (compiled from
40	 * src/ui/lv_font_misans_16_cjk.c, same pattern as xiaozhi_gui's
41	 * font_awesome_*.c) — declared here instead of patching apps_graphics_lvgl. */
42	LV_FONT_DECLARE(lv_font_misans_16_cjk);
43	
44	static const char *TAG = "lvgl_toast";
45	
46	#define TOAST_TITLE_LEN 32
47	#define TOAST_BODY_LEN  160
48	#define TOAST_DEFAULT_MS 4000  /* auto-dismiss if caller passes 0 */
49	
50	/* Heap payload for the async hop into the LVGL thread. */
51	typedef struct {
52	    char title[TOAST_TITLE_LEN];
53	    char body[TOAST_BODY_LEN];
54	    uint32_t bar_color;
55	    uint32_t duration_ms;
56	} toast_payload_t;
57	
58	static lv_obj_t *s_toast = NULL;        /* active toast object, NULL if none */
59	static lv_timer_t *s_timer = NULL;     /* auto-dismiss timer */
60	
61	/* ── Cleanup (must run on LVGL thread) ─────────────────────────── */
62	
63	static void toast_cleanup(void)
64	{
65	    if (s_timer) {
66	        lv_timer_delete(s_timer);
67	        s_timer = NULL;
68	    }
69	    if (s_toast) {
70	        lv_obj_delete(s_toast);
71	        s_toast = NULL;
72	    }
73	}
74	
75	/* ── Event callbacks (LVGL thread) ──────────────────────────────── */
76	
77	static void toast_click_cb(lv_event_t *e)
78	{
79	    (void)e;
80	    syslog(LOG_INFO, "[%s] toast dismissed by tap\n", TAG);
81	    toast_cleanup();
82	}
83	
84	static void toast_anim_ready_cb(lv_anim_t *a)
85	{
86	    lv_obj_t *obj = (lv_obj_t *)a->var;
87	    if (obj == s_toast) {
88	        s_toast = NULL;   /* cleared so toast_cleanup won't double-delete */
89	    }
90	    if (s_timer) {
91	        lv_timer_delete(s_timer);
92	        s_timer = NULL;
93	    }
94	    lv_obj_delete(obj);
95	}
96	
97	static void toast_timeout_cb(lv_timer_t *t)
98	{
99	    (void)t;
100	    s_timer = NULL;  /* timer auto-deletes (repeat_count=1 + auto_delete) */
101	    if (!s_toast) {
102	        return;
103	    }
104	    syslog(LOG_INFO, "[%s] toast auto-dismiss (fade out)\n", TAG);
105	
106	    /* Fade out 300ms then delete */
107	    lv_anim_t a;
108	    lv_anim_init(&a);
109	    lv_anim_set_var(&a, s_toast);
110	    lv_anim_set_values(&a, LV_OPA_COVER, LV_OPA_TRANSP);
111	    lv_anim_set_time(&a, 300);
112	    lv_anim_set_ready_cb(&a, toast_anim_ready_cb);
113	    lv_anim_start(&a);
114	}
115	
116	/* ── Build the toast widget (LVGL thread) ──────────────────────── */
117	
118	static void toast_build(const toast_payload_t *p)
119	{
120	    /* Replace any existing toast */
121	    toast_cleanup();
122	
123	    lv_obj_t *scr = lv_screen_active();
124	    if (!scr) {
125	        syslog(LOG_ERR, "[%s] no active screen\n", TAG);
126	        return;
127	    }
128	
129	    lv_display_t *disp = lv_display_get_default();
130	    lv_coord_t disp_w = disp ? lv_display_get_horizontal_resolution(disp) : 466;
131	    lv_coord_t disp_h = disp ? lv_display_get_vertical_resolution(disp) : 466;
132	    (void)disp_h;
133	
134	    lv_obj_t *toast = lv_obj_create(scr);
135	    if (!toast) {
136	        syslog(LOG_ERR, "[%s] lv_obj_create failed\n", TAG);
137	        return;
138	    }
139	    s_toast = toast;
140	
141	    lv_coord_t w = disp_w - 40;
142	    if (w < 200) w = 200;
143	    lv_obj_set_size(toast, w, 80);
144	    lv_obj_align(toast, LV_ALIGN_TOP_MID, 0, 12);
145	    /* White card (HachimoDock panel): light border + dark drop shadow + colored
146	     * left bar, matching the agent chat card instead of the old qemu dark-purple
147	     * toast.  The full colored border is dropped in favor of the left color bar. */
148	    lv_obj_set_style_bg_color(toast, lv_color_hex(UI_PAL_CARD), 0);
149	    lv_obj_set_style_bg_opa(toast, LV_OPA_COVER, 0);
150	    lv_obj_set_style_border_color(toast, lv_color_hex(UI_PAL_LINE), 0);
151	    lv_obj_set_style_border_width(toast, 1, 0);
152	    lv_obj_set_style_border_side(toast, LV_BORDER_SIDE_FULL, 0);
153	    lv_obj_set_style_radius(toast, 10, 0);
154	    lv_obj_set_style_shadow_width(toast, 4, 0);
155	    lv_obj_set_style_shadow_offset_x(toast, 2, 0);
156	    lv_obj_set_style_shadow_offset_y(toast, 4, 0);
157	    lv_obj_set_style_shadow_color(toast, lv_color_hex(UI_PAL_CARD_SHADOW), 0);
158	    lv_obj_set_style_shadow_opa(toast, LV_OPA_40, 0);
159	    lv_obj_set_style_pad_all(toast, 8, 0);
160	    lv_obj_clear_flag(toast, LV_OBJ_FLAG_SCROLLABLE);
161	    lv_obj_add_flag(toast, LV_OBJ_FLAG_CLICKABLE);
162	    lv_obj_add_event_cb(toast, toast_click_cb, LV_EVENT_CLICKED, NULL);
163	
164	    /* Left color bar */
165	    lv_obj_t *bar = lv_obj_create(toast);
166	    lv_obj_set_size(bar, 6, 64);
167	    lv_obj_align(bar, LV_ALIGN_LEFT_MID, 0, 0);
168	    lv_obj_set_style_bg_color(bar, lv_color_hex(p->bar_color), 0);
169	    lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
170	    lv_obj_set_style_radius(bar, 3, 0);
171	    lv_obj_set_style_border_width(bar, 0, 0);
172	    lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
173	
174	    /* Title label */
175	    lv_obj_t *title = lv_label_create(toast);
176	    if (title) {
177	        lv_label_set_text(title, p->title);
178	        lv_obj_set_style_text_font(title, &lv_font_misans_16_cjk, 0);
179	        lv_obj_set_style_text_color(title, lv_color_hex(UI_PAL_INK), 0);
180	        lv_obj_align(title, LV_ALIGN_TOP_LEFT, 14, 4);
181	    }
182	
183	    /* Body label (ellipsis on overflow) */
184	    lv_obj_t *body = lv_label_create(toast);
185	    if (body) {
186	        lv_label_set_text(body, p->body);
187	        lv_obj_set_style_text_font(body, &lv_font_misans_16_cjk, 0);
188	        lv_obj_set_style_text_color(body, lv_color_hex(UI_PAL_MUTED), 0);
189	        lv_label_set_long_mode(body, LV_LABEL_LONG_DOT);
190	        lv_obj_set_width(body, w - 28);
191	        lv_obj_align(body, LV_ALIGN_BOTTOM_LEFT, 14, -4);
192	    }
193	
194	    /* Auto-dismiss timer */
195	    s_timer = lv_timer_create(toast_timeout_cb, p->duration_ms, NULL);
196	    if (s_timer) {
197	        lv_timer_set_repeat_count(s_timer, 1);
198	        lv_timer_set_auto_delete(s_timer, true);
199	    }
200	
201	    syslog(LOG_INFO, "[%s] toast: %s | %s\n", TAG, p->title, p->body);
202	}
203	
204	/* ── Async entry (LVGL thread) ────────────────────────────────── */
205	
206	static void toast_async_cb(void *data)
207	{
208	    toast_payload_t *p = (toast_payload_t *)data;
209	    if (!p) {
210	        return;
211	    }
212	    toast_build(p);
213	    free(p);
214	}
215	
216	/* ── Public API ───────────────────────────────────────────────── */
217	
218	void lvgl_toast_show_async(const char *title, const char *body,
219	                           uint32_t bar_color, uint32_t duration_ms)
220	{
221	    if (!title || !body) {
222	        return;
223	    }
224	
225	    toast_payload_t *p = (toast_payload_t *)malloc(sizeof(toast_payload_t));
226	    if (!p) {
227	        syslog(LOG_ERR, "[%s] payload alloc failed\n", TAG);
228	        return;
229	    }
230	    strlcpy(p->title, title, sizeof(p->title));
231	    strlcpy(p->body, body, sizeof(p->body));
232	    p->bar_color = bar_color;
233	    p->duration_ms = duration_ms ? duration_ms : TOAST_DEFAULT_MS;
234	
235	    if (lv_async_call(toast_async_cb, p) == LV_RESULT_OK) {
236	        /* async scheduled; payload freed in callback */
237	        return;
238	    }
239	
240	    /* lv_async_call failed — free here to avoid leak */
